$target = Join-Path (Get-Location) '01-java-internals-mastery\README.md'
if (-not (Test-Path -LiteralPath (Split-Path $target))) { throw "Directory not found: $(Split-Path $target)" }
[IO.File]::WriteAllBytes($target, [Convert]::FromBase64String(''))
Write-Host "Updated $target ($((Get-Item -LiteralPath $target).Length) bytes)" -ForegroundColor Green
